CREATE FUNCTION pinchora_normalize_command_control_v1(config JSONB) RETURNS JSONB
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    original JSONB := COALESCE(config->'rules', '{}'::jsonb);
    rules JSONB := original;
    aliases JSONB := '{}'::jsonb;
    item RECORD;
    target TEXT;
BEGIN
    FOR item IN SELECT key, value FROM jsonb_each(original) LOOP
        IF item.key IN ('achievementadmin', 'achievementadmin add', 'achievementadmin edit', 'achievementadmin grant', 'achievementadmin list', 'achievementadmin remove', 'antinuke', 'antinuke disable', 'antinuke enable', 'antinuke events', 'antinuke limits', 'antinuke status', 'antinuke trust', 'antinuke trust add', 'antinuke trust remove', 'antinuke vip', 'antinuke vip add', 'antinuke vip remove', 'automod', 'automod exempt', 'automod exempt channel', 'automod exempt role', 'automod profile', 'automod show', 'automod test', 'automod toggle', 'autoroles', 'autoroles add', 'autoroles list', 'autoroles remove', 'autoroles sticky', 'backup', 'backup export', 'backup import', 'backup list', 'backup restore', 'bio', 'birthdays', 'birthdays preview', 'birthdays settings', 'case', 'color', 'color setup', 'commandcontrol', 'commandcontrol alias', 'commandcontrol reset', 'commandcontrol set', 'commandcontrol show', 'config', 'config critters', 'config gambling', 'config goodbye', 'config join-role', 'config language', 'config level-roles', 'config level-roles add', 'config level-roles list', 'config level-roles mode', 'config level-roles remove', 'config level-roles sync', 'config leveling', 'config log', 'config log-events', 'config log-ignore', 'config moderation', 'config modules', 'config modules channels', 'config modules show', 'config modules toggle', 'config partygames', 'config points', 'config prefix', 'config prefix reset', 'config prefix set', 'config prefix show', 'config rep-roles', 'config rep-roles add', 'config rep-roles list', 'config rep-roles remove', 'config show', 'config store', 'config store add', 'config store list', 'config store remove', 'config suggestions', 'config surge', 'config warn-ladder', 'config welcome', 'config welcome-card', 'config xp', 'config xp clear', 'config xp multiplier', 'config xp show', 'config xp voice', 'counters', 'counters add', 'counters list', 'counters remove', 'customcommand', 'customcommand create', 'customcommand delete', 'customcommand edit', 'customcommand info', 'customcommand list', 'event', 'event template', 'feeds', 'feeds add', 'feeds edit', 'feeds list', 'feeds remove', 'feeds test', 'inviteadmin', 'inviteadmin bonus-add', 'inviteadmin bonus-remove', 'inviteadmin post', 'inviteadmin reward-add', 'inviteadmin reward-remove', 'inviteadmin settings', 'lock', 'monthly', 'nick', 'plaza', 'plaza edit', 'points', 'points give', 'points take', 'raid', 'raid lockdown', 'raid status', 'raid unlock', 'reason', 'role', 'role add', 'role remove', 'roles', 'roles add', 'roles panel', 'roles post', 'roles remove', 'roles temp', 'schedule', 'schedule add', 'schedule list', 'schedule pause', 'schedule preview', 'schedule remove', 'schedule resume', 'schedule run-now', 'slowmode', 'starboard', 'starboard edit', 'starboard list', 'starboard remove', 'starboard setup', 'starboard top', 'starboard votes', 'starboard votes add', 'starboard votes list', 'starboard votes remove', 'sticky', 'sticky remove', 'sticky set', 'sticky show', 'suggestion', 'suggestion approve', 'suggestion deny', 'tickets', 'tickets panel', 'tickets panel create', 'tickets panel delete', 'tickets panel edit', 'tickets panel list', 'tickets panel post', 'tickets settings', 'unban', 'unlock', 'untimeout', 'unwarn', 'verification', 'verification message', 'verification mode', 'verification post', 'verification setup', 'voice', 'voice creators', 'voice creators add', 'voice creators list', 'voice creators remove', 'warnings', 'weekly', 'wrapped', 'xp', 'xp add', 'xp import', 'xp import mee6', 'xp remove', 'xp reset', 'xp reset-all', 'xp set') THEN
            rules := rules - item.key;
            FOR target IN SELECT * FROM pinchora_command_targets_v1(item.key) LOOP
                rules := jsonb_set(rules, ARRAY[target],
                    COALESCE(rules->target, '{}'::jsonb) || jsonb_build_object('constraints',
                        COALESCE(rules->target->'constraints', '{}'::jsonb) || jsonb_build_object(item.key, item.value)));
            END LOOP;
        END IF;
    END LOOP;
    FOR item IN SELECT key, value FROM jsonb_each_text(COALESCE(config->'aliases', '{}'::jsonb)) LOOP
        aliases := aliases || jsonb_build_object(item.key, pinchora_command_path_v1(item.value));
    END LOOP;
    RETURN config || jsonb_build_object('rules', rules, 'aliases', aliases);
END
$$;

CREATE FUNCTION pinchora_command_paths_on_write() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.config := pinchora_normalize_command_control_v1(NEW.config);
    RETURN NEW;
END
$$;
CREATE TRIGGER command_paths_on_write BEFORE INSERT OR UPDATE OF config ON command_control
FOR EACH ROW EXECUTE FUNCTION pinchora_command_paths_on_write();
UPDATE command_control SET config = pinchora_normalize_command_control_v1(config), revision = revision + 1
WHERE config IS DISTINCT FROM pinchora_normalize_command_control_v1(config);

-- Exact Discord override data is retained separately from additive bot rules and portable backups.
-- Entries contain role/user/channel targets with Discord precedence; never convert them to allowlists.
CREATE TABLE command_permission_snapshots (
    guild_id BIGINT NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,
    application_id BIGINT NOT NULL,
    snapshot JSONB NOT NULL,
    captured_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (guild_id, application_id)
);
